#!/usr/bin/env python3
"""Street Legends frontend: Activity Centers (phase 1 — NO items, NO games, NO shop).

What it adds:
- Map markers for university/college Activity Centers with the literal
  game-controller icon (visible to EVERYONE — no friends filter).
- Tap -> popup with ONLY an Enter button (the popup's built-in close X
  is the only other control; no buy/sell/move/hide options).
- Enter -> full-screen interior on the hall picture (embedded below as a
  data URI; the GitHub push tool cannot carry binary files), showing NO
  menu — just "Inside now:" with YOUR name first, then your FRIENDS who
  are inside. Strangers inside are NOT listed (frontend filter).
- Presence lifecycle mirrors the house pattern: enter on open, poll
  every 15s, heartbeat every 30s, leave on exit. A single LEAVE button
  returns to the map.
- Center identity: the backend seeds one center per ~500m grid cell with
  a deterministic id ("activity_center_<lat>_<lng>"), so every phone
  agrees on the same center and the same presence room.

Frontend / Expo Go only. Run from /app. No build, no Deploy for this
patch itself (the backend patch needs Publish separately).
"""
import re
import sys
from pathlib import Path

INDEX = Path("frontend/app/(tabs)/index.tsx")
API = Path("frontend/services/api.ts")
QUERIES = Path("frontend/hooks/useMapQueries.ts")
GAMEMAP = Path("frontend/components/GameMap.tsx")
MARKER = "ACTIVITY_CENTER_FRONTEND_OK"

ACTIVITY_CENTER_BG = "data:image/jpeg;base64,"

API_FNS_TEXT = """
// ACTIVITY_CENTER_API: activity center spawn + presence client.
export const spawnActivityCenters = async (latitude: number, longitude: number, playerLevel: number = 1) => {
  const response = await api.get(`/activity-centers/spawn?latitude=${latitude}&longitude=${longitude}&player_level=${playerLevel}`);
  return response.data;
};
export const centerEnterPresence = async (centerId: string, playerId: string, playerName: string): Promise<any> => {
  const response = await api.post(`/activity-centers/${centerId}/enter`, { player_id: playerId, player_name: playerName });
  return response.data;
};
export const centerLeavePresence = async (centerId: string, playerId: string): Promise<any> => {
  const response = await api.post(`/activity-centers/${centerId}/leave`, { player_id: playerId });
  return response.data;
};
export const centerHeartbeatPresence = async (centerId: string, playerId: string, playerName: string): Promise<any> => {
  const response = await api.post(`/activity-centers/${centerId}/heartbeat`, { player_id: playerId, player_name: playerName });
  return response.data;
};
export const getCenterPresence = async (centerId: string): Promise<any> => {
  const response = await api.get(`/activity-centers/${centerId}/presence`);
  return response.data;
};
"""

CENTER_SPREAD = """    ...nearbyActivityCenters.map((c: any) => ({
      id: c.id,
      coordinate: { latitude: c.latitude, longitude: c.longitude },
      type: 'activityCenter' as const,
      name: c.name,
      icon: '🎮',
    })),
"""

CENTER_POPUP = """          {selectedMarker.type === 'activityCenter' && (
            <View>
              <View style={styles.popupHeader}>
                <Text style={{ fontSize: 28 }}>🎮</Text>
                <View style={styles.popupHeaderText}>
                  <Text style={styles.popupTitle}>{selectedMarker.data.name}</Text>
                  <Text style={styles.popupSubtitle}>Activity Center • Everyone welcome</Text>
                </View>
              </View>
              <TouchableOpacity
                style={[styles.actionButton, { backgroundColor: '#7b1fa2' }]}
                onPress={() => {
                  const c = selectedMarker.data;
                  setSelectedMarker(null);
                  setActiveCenter(c);
                }}
              >
                <Text style={styles.actionButtonText}>ENTER</Text>
              </TouchableOpacity>
            </View>
          )}

"""

CENTER_STATE_EFFECT = """  // ACTIVITY_CENTER: interior state (no menu, just who is inside).
  const [activeCenter, setActiveCenter] = useState<any | null>(null);
  const [centerOccupants, setCenterOccupants] = useState<any[]>([]);
  const [centerFriendIds, setCenterFriendIds] = useState<string[]>([]);

  // ACTIVITY_CENTER: presence lifecycle — enter on open, poll 15s, heartbeat 30s, leave on exit.
  useEffect(() => {
    if (!activeCenter || !playerId) return;
    let stopped = false;
    const centerName = (player as any)?.name || 'Player';
    const loadCenterOccupants = async () => {
      try {
        const res: any = await getCenterPresence(activeCenter.id);
        if (!stopped && res?.occupants) setCenterOccupants(res.occupants);
      } catch (_) {}
    };
    (async () => {
      try {
        const friends: any[] = await getFriendsList(playerId);
        if (!stopped) setCenterFriendIds((friends || []).map((f: any) => f.id));
      } catch (_) {}
      try {
        const res: any = await centerEnterPresence(activeCenter.id, playerId, centerName);
        if (!stopped && res?.occupants) setCenterOccupants(res.occupants);
      } catch (_) {}
    })();
    const hb = setInterval(async () => {
      try { await centerHeartbeatPresence(activeCenter.id, playerId, centerName); } catch (_) {}
    }, 30000);
    const poll = setInterval(loadCenterOccupants, 15000);
    return () => {
      stopped = true;
      clearInterval(hb);
      clearInterval(poll);
      centerLeavePresence(activeCenter.id, playerId).catch(() => {});
    };
  }, [activeCenter?.id, playerId]);
"""

CENTER_MODAL = """      {/* ACTIVITY_CENTER interior — no menu, just who is inside. */}
      <Modal visible={!!activeCenter} animationType="slide" onRequestClose={() => setActiveCenter(null)}>
        <ImageBackground source={{ uri: ACTIVITY_CENTER_BG }} style={{ flex: 1 }} resizeMode="cover">
          <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', padding: 20, paddingTop: 60 }}>
            <Text style={{ fontSize: 26, fontWeight: 'bold', color: '#fff' }}>{activeCenter?.name || 'Activity Center'}</Text>
            <Text style={{ fontSize: 14, color: '#e0e0e0', marginTop: 4 }}>Activity Center</Text>
            <Text style={{ fontSize: 18, fontWeight: 'bold', color: '#fff', marginTop: 24, marginBottom: 8 }}>Inside now:</Text>
            {(() => {
              const friendIds = centerFriendIds || [];
              const shown = (centerOccupants || []).filter((o: any) => o.player_id === playerId || friendIds.indexOf(o.player_id) !== -1);
              const me = shown.filter((o: any) => o.player_id === playerId);
              const friends = shown.filter((o: any) => o.player_id !== playerId);
              const ordered = me.concat(friends);
              if (ordered.length === 0) return (<Text style={{ fontSize: 16, color: '#fff' }}>{(player as any)?.name || 'You'}</Text>);
              return ordered.map((o: any) => (
                <Text key={o.player_id} style={{ fontSize: 16, color: '#fff', marginBottom: 6 }}>
                  {o.player_id === playerId ? '★ ' : ''}{o.player_name}
                </Text>
              ));
            })()}
            <TouchableOpacity
              style={{ marginTop: 32, backgroundColor: '#7b1fa2', padding: 14, borderRadius: 10, alignItems: 'center' }}
              onPress={() => setActiveCenter(null)}
            >
              <Text style={{ color: '#fff', fontWeight: 'bold', fontSize: 16 }}>LEAVE</Text>
            </TouchableOpacity>
          </View>
        </ImageBackground>
      </Modal>

"""


def _delta(s):
    return (s.count("{") - s.count("}"), s.count("(") - s.count(")"))


def main():
    landed = []

    # --- Part 1: services/api.ts ---
    if not API.exists():
        print("WARNING: services/api.ts not found - Activity Center api functions NOT added")
    elif "spawnActivityCenters" in API.read_text(errors="ignore"):
        print("ACTIVITY_CENTER_FRONTEND_API_ALREADY_APPLIED")
        landed.append("api")
    else:
        asrc = API.read_text(errors="ignore")
        anchor = "// ============== NIGHTCLUBS =============="
        if anchor not in asrc:
            print("WARNING: nightclubs section anchor not found in api.ts - Activity Center api functions NOT added")
        else:
            asrc = asrc.replace(anchor, API_FNS_TEXT + "\n" + anchor, 1)
            API.write_text(asrc)
            print("ACTIVITY_CENTER_FRONTEND_API_OK")
            landed.append("api")

    # --- Part 2: hooks/useMapQueries.ts ---
    if not QUERIES.exists():
        print("WARNING: hooks/useMapQueries.ts not found - Activity Centers NOT fetched for the map")
    elif "spawnActivityCenters" in QUERIES.read_text(errors="ignore") and "activityCenters" in QUERIES.read_text(errors="ignore"):
        print("ACTIVITY_CENTER_FRONTEND_QUERIES_ALREADY_APPLIED")
        landed.append("queries")
    else:
        qsrc = QUERIES.read_text(errors="ignore")
        qorig = qsrc
        if "spawnActivityCenters" not in qsrc:
            if "  spawnShootouts,\n" in qsrc:
                qsrc = qsrc.replace("  spawnShootouts,\n", "  spawnShootouts,\n  spawnActivityCenters,\n", 1)
            else:
                print("WARNING: api import anchor not found in useMapQueries.ts - spawnActivityCenters import NOT added")
        if "activityCenters: any[];" not in qsrc:
            if "  shootouts: any[];\n" in qsrc:
                qsrc = qsrc.replace("  shootouts: any[];\n", "  shootouts: any[];\n  activityCenters: any[];\n", 1)
            else:
                print("WARNING: MapEntitiesData anchor not found - activityCenters field NOT added")
        if "spawnActivityCenters(latitude" not in qsrc:
            if "        spawnShootouts(latitude, longitude, playerLevel),\n" in qsrc:
                qsrc = qsrc.replace("        spawnShootouts(latitude, longitude, playerLevel),\n",
                                    "        spawnShootouts(latitude, longitude, playerLevel),\n        spawnActivityCenters(latitude, longitude, playerLevel),\n", 1)
            else:
                print("WARNING: entity fetch anchor not found in useMapQueries.ts - centers NOT fetched")
        if "activityCenters: results[14]" not in qsrc:
            if "        shootouts: results[13].status === 'fulfilled' ? results[13].value : [],\n" in qsrc:
                qsrc = qsrc.replace("        shootouts: results[13].status === 'fulfilled' ? results[13].value : [],\n",
                                    "        shootouts: results[13].status === 'fulfilled' ? results[13].value : [],\n        activityCenters: results[14].status === 'fulfilled' ? results[14].value : [],\n", 1)
            else:
                print("WARNING: entity return anchor not found in useMapQueries.ts - centers NOT returned to the map")
        if qsrc != qorig:
            QUERIES.write_text(qsrc)
            print("ACTIVITY_CENTER_FRONTEND_QUERIES_OK")
            landed.append("queries")

    # --- Part 3: app/(tabs)/index.tsx ---
    if not INDEX.exists():
        print("WARNING: app/(tabs)/index.tsx not found - map markers, popup and interior NOT added")
    else:
        src = INDEX.read_text(errors="ignore")
        orig = src
        iorig = _delta(src)

        # 3a. ImageBackground import.
        if "ImageBackground" in src:
            print("ACTIVITY_CENTER_FRONTEND_IMPORT_ALREADY_APPLIED")
            landed.append("import")
        elif "  Image,\n} from 'react-native';" in src:
            src = src.replace("  Image,\n} from 'react-native';",
                              "  Image,\n  ImageBackground,\n} from 'react-native';", 1)
            print("ACTIVITY_CENTER_FRONTEND_IMPORT_OK")
            landed.append("import")
        else:
            print("WARNING: react-native import anchor not found - ImageBackground NOT imported (interior background will fail)")

        # 3b. API + friends imports.
        need = ["spawnActivityCenters", "centerEnterPresence", "centerLeavePresence",
                "centerHeartbeatPresence", "getCenterPresence", "getFriendsList"]
        if all(n in src for n in need):
            print("ACTIVITY_CENTER_FRONTEND_APIIMPORT_ALREADY_APPLIED")
            landed.append("apiimport")
        elif "  sendFriendRequest,\n} from '../../services/api';" in src:
            src = src.replace("  sendFriendRequest,\n} from '../../services/api';",
                              "  sendFriendRequest,\n  spawnActivityCenters,\n  centerEnterPresence,\n  centerLeavePresence,\n  centerHeartbeatPresence,\n  getCenterPresence,\n  getFriendsList,\n} from '../../services/api';", 1)
            print("ACTIVITY_CENTER_FRONTEND_APIIMPORT_OK")
            landed.append("apiimport")
        else:
            print("WARNING: services/api import anchor not found in index.tsx - center functions NOT imported")

        # 3c. Background data-URI const.
        if "ACTIVITY_CENTER_BG" in src:
            print("ACTIVITY_CENTER_FRONTEND_BG_ALREADY_APPLIED")
            landed.append("bg")
        elif "export default function MapScreen() {" in src:
            src = src.replace("export default function MapScreen() {",
                              "const ACTIVITY_CENTER_BG = \"" + ACTIVITY_CENTER_BG + "\";\n\nexport default function MapScreen() {", 1)
            print("ACTIVITY_CENTER_FRONTEND_BG_OK")
            landed.append("bg")
        else:
            print("WARNING: MapScreen anchor not found - hall background NOT added")

        # 3d. selectedMarker type union.
        if "'activityCenter'" in src:
            print("ACTIVITY_CENTER_FRONTEND_TYPE_ALREADY_APPLIED")
            landed.append("type")
        elif "type: 'monster' | 'mission' | 'bounty' | 'player' | 'shop' | 'restaurant' | 'nightclub';" in src:
            src = src.replace("type: 'monster' | 'mission' | 'bounty' | 'player' | 'shop' | 'restaurant' | 'nightclub';",
                              "type: 'monster' | 'mission' | 'bounty' | 'player' | 'shop' | 'restaurant' | 'nightclub' | 'activityCenter';", 1)
            print("ACTIVITY_CENTER_FRONTEND_TYPE_OK")
            landed.append("type")
        else:
            print("WARNING: selectedMarker type anchor not found - center popup type NOT added")

        # 3e. State + presence lifecycle effect.
        if "activeCenter" in src and "centerEnterPresence(activeCenter.id" in src:
            print("ACTIVITY_CENTER_FRONTEND_STATE_ALREADY_APPLIED")
            landed.append("state")
        elif "  } | null>(null);\n  const [isTracking, setIsTracking] = useState(false);" in src:
            src = src.replace("  } | null>(null);\n  const [isTracking, setIsTracking] = useState(false);",
                              "  } | null>(null);\n" + CENTER_STATE_EFFECT + "  const [isTracking, setIsTracking] = useState(false);", 1)
            print("ACTIVITY_CENTER_FRONTEND_STATE_OK")
            landed.append("state")
        else:
            print("WARNING: selectedMarker state anchor not found - center state/effect NOT added")

        # 3f. Nearby memo.
        if "nearbyActivityCenters" in src:
            print("ACTIVITY_CENTER_FRONTEND_MEMO_ALREADY_APPLIED")
            landed.append("memo")
        elif "  const nearbyRestaurants = useMemo(() => entitiesData?.restaurants || [], [entitiesData?.restaurants]);" in src:
            src = src.replace("  const nearbyRestaurants = useMemo(() => entitiesData?.restaurants || [], [entitiesData?.restaurants]);",
                              "  const nearbyRestaurants = useMemo(() => entitiesData?.restaurants || [], [entitiesData?.restaurants]);\n  const nearbyActivityCenters = useMemo(() => entitiesData?.activityCenters || [], [entitiesData?.activityCenters]);", 1)
            print("ACTIVITY_CENTER_FRONTEND_MEMO_OK")
            landed.append("memo")
        else:
            print("WARNING: nearby memo anchor not found - centers NOT read from map data")

        # 3g. Marker spread + useMemo deps.
        if "type: 'activityCenter' as const," in src:
            print("ACTIVITY_CENTER_FRONTEND_MARKERS_ALREADY_APPLIED")
            landed.append("markers")
        elif "    ...nearbyNightclubs.map((nc) => ({" in src:
            src = src.replace("    ...nearbyNightclubs.map((nc) => ({", CENTER_SPREAD + "    ...nearbyNightclubs.map((nc) => ({", 1)
            deps_old = "nearbyRestaurants, nearbyNightclubs, nearbyBanks, nearbyCastles, nearbyCarChases, nearbyRunaways, nearbyPackageGrabs, nearbyShootouts, localCooldowns]);"
            if deps_old in src:
                src = src.replace(deps_old, "nearbyRestaurants, nearbyActivityCenters, nearbyNightclubs, nearbyBanks, nearbyCastles, nearbyCarChases, nearbyRunaways, nearbyPackageGrabs, nearbyShootouts, localCooldowns]);", 1)
            else:
                print("WARNING: mapMarkers deps anchor not found - center markers may not refresh")
            print("ACTIVITY_CENTER_FRONTEND_MARKERS_OK")
            landed.append("markers")
        else:
            print("WARNING: mapMarkers anchor not found - center markers NOT added to the map")

        # 3h. Marker press branch + useCallback deps.
        if "marker.type === 'activityCenter'" in src:
            print("ACTIVITY_CENTER_FRONTEND_PRESS_ALREADY_APPLIED")
            landed.append("press")
        elif "    } else if (marker.type === 'restaurant') {" in src:
            anchor = ("    } else if (marker.type === 'restaurant') {\n"
                      "      const restaurant = nearbyRestaurants.find((r) => r.id === marker.id);\n"
                      "      if (restaurant) setSelectedMarker({ type: 'restaurant', data: restaurant });")
            branch = anchor + ("\n    } else if (marker.type === 'activityCenter') {\n"
                               "      const center = nearbyActivityCenters.find((c) => c.id === marker.id);\n"
                               "      if (center) setSelectedMarker({ type: 'activityCenter', data: center });")
            src = src.replace(anchor, branch, 1)
            deps_old = "nearbyRestaurants, nearbyNightclubs, nearbyBanks, nearbyCasinos, nearbyCastles, nearbyCarChases, nearbyRunaways, nearbyPackageGrabs, nearbyShootouts]);"
            if deps_old in src:
                src = src.replace(deps_old, "nearbyRestaurants, nearbyActivityCenters, nearbyNightclubs, nearbyBanks, nearbyCasinos, nearbyCastles, nearbyCarChases, nearbyRunaways, nearbyPackageGrabs, nearbyShootouts]);", 1)
            else:
                print("WARNING: handleMarkerPress deps anchor not found - center taps may use a stale list")
            print("ACTIVITY_CENTER_FRONTEND_PRESS_OK")
            landed.append("press")
        else:
            print("WARNING: handleMarkerPress anchor not found - center taps NOT wired")

        # 3i. Popup (Enter only) — inserted before the nightclub popup.
        if "Activity Center • Everyone welcome" in src:
            print("ACTIVITY_CENTER_FRONTEND_POPUP_ALREADY_APPLIED")
            landed.append("popup")
        elif "          {selectedMarker.type === 'nightclub' && (" in src:
            src = src.replace("          {selectedMarker.type === 'nightclub' && (",
                              CENTER_POPUP + "          {selectedMarker.type === 'nightclub' && (", 1)
            print("ACTIVITY_CENTER_FRONTEND_POPUP_OK")
            landed.append("popup")
        else:
            print("WARNING: popup anchor not found - center popup NOT added")

        # 3j. Interior modal (no menu, just who is inside).
        if "ACTIVITY_CENTER interior" in src:
            print("ACTIVITY_CENTER_FRONTEND_INTERIOR_ALREADY_APPLIED")
            landed.append("interior")
        elif "      {/* Popup */}" in src:
            src = src.replace("      {/* Popup */}", CENTER_MODAL + "      {/* Popup */}", 1)
            print("ACTIVITY_CENTER_FRONTEND_INTERIOR_OK")
            landed.append("interior")
        else:
            print("WARNING: popup section anchor not found - center interior NOT added")

        if _delta(src) != iorig:
            print("WARNING: balance changed - index.tsx NOT written")
            return 1
        if src != orig:
            INDEX.write_text(src)

    # --- Part 4: components/GameMap.tsx (marker icon + label) ---
    if not GAMEMAP.exists():
        print("WARNING: components/GameMap.tsx not found - center marker icon NOT added (marker would show '?')")
    else:
        gsrc = GAMEMAP.read_text(errors="ignore")
        gorig = gsrc
        gdelta = _delta(gsrc)
        if "activityCenter" in gsrc:
            print("ACTIVITY_CENTER_FRONTEND_MAP_ALREADY_APPLIED")
            landed.append("map")
        else:
            if "casino: '#d4af37' };" in gsrc:
                gsrc = gsrc.replace("casino: '#d4af37' };", "casino: '#d4af37', activityCenter: '#7b1fa2' };", 1)
            else:
                print("WARNING: markerColors anchor not found - center marker color NOT added")
            if "casino: '🎰' };" in gsrc:
                gsrc = gsrc.replace("casino: '🎰' };", "casino: '🎰', activityCenter: '🎮' };", 1)
            else:
                print("WARNING: markerIcons anchor not found - center marker icon NOT added")
            if "var isLocationMarker = (m.type === 'restaurant' || m.type === 'nightclub');" in gsrc:
                gsrc = gsrc.replace("var isLocationMarker = (m.type === 'restaurant' || m.type === 'nightclub');",
                                    "var isLocationMarker = (m.type === 'restaurant' || m.type === 'nightclub' || m.type === 'activityCenter');", 1)
            else:
                print("WARNING: isLocationMarker anchor not found - center marker size may differ")
            branch_anchor = "} else if (m.type === 'bank') {"
            if branch_anchor in gsrc:
                branch = ("} else if (m.type === 'activityCenter') {\n"
                          "              var acName = m.name || 'Activity Center';\n"
                          "              markerHTML = '<div style=\"width:48px;height:62px;position:relative;display:flex;flex-direction:column;align-items:center;\">' +\n"
                          "                '<div style=\"width:42px;height:42px;border-radius:10px;background:linear-gradient(135deg,#7b1fa2,#4a148c);display:flex;align-items:center;justify-content:center;border:3px solid #fff;box-shadow:0 3px 10px rgba(123,31,162,0.6);font-size:22px;cursor:pointer;\">🎮</div>' +\n"
                          "                '<div style=\"position:absolute;bottom:0;left:50%;transform:translateX(-50%);background:rgba(123,31,162,0.9);color:#fff;padding:1px 6px;border-radius:4px;font-size:7px;font-weight:bold;white-space:nowrap;z-index:10;border:1px solid #fff;\">' + acName + '</div>' +\n"
                          "                '</div>';\n"
                          "            \n" + branch_anchor)
                gsrc = gsrc.replace(branch_anchor, branch, 1)
                print("ACTIVITY_CENTER_FRONTEND_MAP_OK")
                landed.append("map")
            else:
                print("WARNING: marker branch anchor not found - center marker label NOT added")
            if _delta(gsrc) != gdelta:
                print("WARNING: balance changed - GameMap.tsx NOT written")
                return 1
            if gsrc != gorig:
                GAMEMAP.write_text(gsrc)

    if len(landed) == 13:
        print(MARKER)
    else:
        print("ACTIVITY_CENTER_FRONTEND_PARTIAL: " + ",".join(landed))
    return 0


if __name__ == "__main__":
    sys.exit(main())
